-- ============================================================
-- SafariConnect: 01 - load the raw booking export
--
-- Creates schema safari_connect and the staging table
-- bookings_staging with all 290 rows exactly as they arrived
-- (every column TEXT, nothing cleaned). Run this file first.
--
-- NOTE: the first line drops and recreates the safari_connect
-- schema. If you already have a schema with that name that you
-- want to keep, change the name at the top of each file.
-- ============================================================
DROP SCHEMA IF EXISTS safari_connect CASCADE;
CREATE SCHEMA safari_connect;
SET search_path TO safari_connect;

CREATE TABLE bookings_staging (
    booking_id        TEXT,
    passenger_name    TEXT,
    passenger_phone   TEXT,
    passenger_gender  TEXT,
    passenger_city    TEXT,
    route_code        TEXT,
    route_from        TEXT,
    route_to          TEXT,
    vehicle_plate     TEXT,
    vehicle_type      TEXT,
    driver_name       TEXT,
    driver_rating     TEXT,
    departure_date    TEXT,
    departure_time    TEXT,
    seat_class        TEXT,
    seats_booked      TEXT,
    fare_per_seat     TEXT,
    total_fare        TEXT,
    payment_method    TEXT,
    booking_status    TEXT,
    trip_rating       TEXT
);


-- check: expect 290
SELECT COUNT(*) AS staging_rows FROM bookings_staging;
